	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Field
	 */
		public Field createField( CreateFieldCommand command ) {

		Field entity = new Field();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setFieldId( command.getFieldId() );
            entity.setName( command.getName() );
            entity.setFieldCode( command.getFieldCode() );
            entity.setArea( command.getArea() );
            entity.setBoundary( command.getBoundary() );
            entity.setAreaUnit( command.getAreaUnit() );
            entity.setSoilTexture( command.getSoilTexture() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Field {0} ", entity.toString() );

		return entity;
	}

